def photo_reel(files, reel_type, name="", texts="", music=None, duration=24, folder=""):
    """Photo reel tab: photos in, a typed reel out. Yields (status, log, video)."""
    import time
    from shortsflow import onboarding
    from engine.photo_reel_types import PHOTO_EXTS
    photos = [f for f in (files or []) if str(getattr(f, "name", f)).lower().endswith(PHOTO_EXTS)]
    session = os.path.join(ROOT, "sessions", time.strftime("reel_%Y%m%d_%H%M%S"))
    if not photos and (folder or "").strip() and web_args.remote_access():
        raise gr.Error(PC_PATH_MESSAGE)
    local = web_args.local_photo_folder(folder, PHOTO_EXTS) if not photos else None       # a folder already on this PC: used where it is
    if not photos and (folder or "").strip() and not local:
        raise gr.Error("That folder does not exist or has fewer than 3 photos (JPG, PNG or WebP).")
    if not local and len(photos) < 3:
        raise gr.Error("Add at least 3 photos (JPG, PNG or WebP), or paste a folder path.")
    folder = local or web_args.stage_photos(photos, os.path.join(session, "photos"))
    cmd = [*_pipeline_cmd(), *web_args.photo_reel_args(folder, reel_type, name, texts, music, duration, session)]
    progress, seen = onboarding.Progress(start="📸 Looking at your photos...", steps=onboarding.PHOTO_STEPS), 0
    status = progress.message
    yield status, "", None
    log = ""
    for log, _videos in _run(cmd):
        lines = log.splitlines()
        for line in lines[seen:]:
            status = progress.feed(line)
        seen = len(lines)
        yield progress.display(), log, None
    video = web_args.find_photo_reel(session)
    if video:
        yield "✅ Done! Your reel is ready below.", log, video
        return
    reason = next((ln.split("]", 1)[1].strip() for ln in reversed(log.splitlines()) if ln.startswith("[Error]")), "")
    yield "❌ No reel was made." + (f" {reason}" if reason else " Open 'Technical details' for the reason."), log, None


def case_plan(topic, sources, template):
    """Case explainer tab, review step: write only the script, so it can be read and edited before anything is spoken or rendered.
    Yields (status, log, script text, session folder)."""
    import time
    from engine import case_study
    session = os.path.join(ROOT, "sessions", time.strftime("case_%Y%m%d_%H%M%S"))
    try:
        args = web_args.case_args(topic, sources, template, session_dir=session, plan_only=True)
    except ValueError as e:
        raise gr.Error(str(e))
    yield "📝 Reading the sources and writing the script...", "", "", ""
    log = ""
    for log, _videos in _run([*_pipeline_cmd(), *args]):
        yield "📝 Reading the sources and writing the script...", log, "", ""
    try:
        with open(os.path.join(session, "script.json"), encoding="utf-8") as f:
            script = json.load(f)
    except (OSError, ValueError):
        reason = next((ln.split("]", 1)[1].strip() for ln in reversed(log.splitlines()) if ln.startswith("[Error]")), "")
        yield "❌ No script was written." + (f" {reason}" if reason else " Open 'Technical details' for the reason."), log, "", ""
        return
    note = "" if script.get("verified") else " It is UNVERIFIED: no source was given."
    yield ("✅ The script is ready. Read it, change what you want (any text, the labels, the stock-footage words, or delete a whole section), "
           "then press **Render this script**." + note), log, case_study.script_to_text(script), session


def case_render_script(script_text, session, theme_label, formats, no_manim, background_label, background_file, draft, avatar="off", transition="number", narrator="standard"):
    """Case explainer tab, review step: save the edited script and render it (the narration is made from the edited text)."""
    from engine import case_study
    if not session or not os.path.isfile(os.path.join(session, "script.json")):
        raise gr.Error("Write the script first.")
    with open(os.path.join(session, "script.json"), encoding="utf-8") as f:
        base = json.load(f)
    try:
        script = case_study.script_from_text(script_text, base)
    except ValueError as e:
        raise gr.Error(str(e))
    original = os.path.join(session, "script_original.json")
    if not os.path.exists(original):
        with open(original, "w", encoding="utf-8") as f:
            json.dump(base, f, indent=1, ensure_ascii=False)
    with open(os.path.join(session, "script.json"), "w", encoding="utf-8") as f:
        json.dump(script, f, indent=1, ensure_ascii=False)
    yield from case_video("", "", "case", theme_label, formats, no_manim, background_label, background_file, "", draft, resume_path=session, avatar=avatar,
                          transition=transition, narrator=narrator)


def case_video(topic, sources, template, theme_label, formats, no_manim, background_label, background_file, resume_label="", draft=False, layouts="auto",
               resume_path=None, avatar="off", transition="number", narrator="standard", voice_sample=None):
    """Case explainer tab: a topic and sources in, a sectioned explainer video out. Yields (status, log, videos)."""
    import time
    old = resume_path or dict(web_args.list_case_sessions(ROOT, limit=50)).get(resume_label or "")
    session = old or os.path.join(ROOT, "sessions", time.strftime("case_%Y%m%d_%H%M%S"))
    theme = next((k for k, v in web_args.CASE_THEME_LABELS.items() if v == theme_label), "dark")
    try:
        background = web_args.CASE_BACKGROUNDS.get(background_label, "footage")
        if background == "file" and not background_file:
            raise ValueError("Add an image or video file, or choose another background.")
        args = web_args.case_args(topic, sources, template, theme, formats, no_manim, False, session, background, background_file,
                                  resume=old, draft=bool(draft), layouts=layouts, avatar=avatar, transition=transition, narrator=narrator,
                                  voice_sample=voice_sample)
    except ValueError as e:
        raise gr.Error(str(e))
    cmd = [*_pipeline_cmd(), *args]
    status = "📝 Reading the sources and writing the script..."
    yield status, "", None
    log, seen = "", 0
    for log, _videos in with_auto_publish(_run(cmd)):
        lines = log.splitlines()
        for line in lines[seen:]:
            if line.startswith("[Log] Script:"):
                status = "🎙️ " + line.split("]", 1)[1].strip() + " Making the voice, the scenes and the animation..."
            elif "SUCCESS!" in line:
                status = "🎬 " + line.split("]", 1)[1].strip().split(":")[0] + " is ready. " + ("Rendering the next shape..." if "16:9" in line and "9:16" in (formats or []) else "")
        seen = len(lines)
        yield status, log, None
    videos = web_args.find_case_videos(session, draft=bool(draft))
    if videos:
        yield f"✅ Done! {len(videos)} video{'s' if len(videos) != 1 else ''} ready below (also in {session})." + (" Auto-publish ran: see the log." if "[Publish]" in log else ""), log, videos
        return
    reason = next((ln.split("]", 1)[1].strip() for ln in reversed(log.splitlines()) if ln.startswith("[Error]")), "")
    yield "❌ No video was made." + (f" {reason}" if reason else " Open 'Technical details' for the reason."), log, None


def generate_short(mode, category, prompt, script, vibe, voice, caption_style, aspect_ratio,
                   use_remotion, llm_provider, tts_provider):
    cmd = [*_pipeline_cmd(), "--mode", mode, "--vibe", vibe]
    for flag, value in (("--category", category), ("--prompt", prompt), ("--script", script), ("--voice", voice)):
        if value and value.strip():
            cmd += [flag, value.strip()]
    cmd += _common_args(caption_style, aspect_ratio, use_remotion, llm_provider, tts_provider)
    yield from _run(cmd)


