def apply_review_hashtags(path, keyword, tags, cards):
    from shortsflow.hashtag_research import parse_tags
    desc, values, message = apply_saved_hashtags(path, keyword, tags)
    out = []
    for card in cards or []:
        card = dict(card)
        if card.get("video") == path:
            card.update(description=desc, tags=parse_tags(values))
        out.append(card)
    return out, message


