def publisher_library(shape_label="All formats", project=None):
    """Load projects without hiding older sessions behind the old 80-video cap."""
    from shortsflow import settings
    videos = settings.list_videos(ROOT, shape=SHAPE_LABELS.get(shape_label, "all"), limit=10000)
    sessions = os.path.join(ROOT, "sessions")
    projects = {}
    for video in videos:
        relative = os.path.relpath(video["path"], sessions)
        if any(part.lower() in ("temp_segments", "segments", "render_temp") for part in relative.split(os.sep)[:-1]):
            continue
        session = os.path.join(sessions, relative.split(os.sep)[0])
        video["project"] = session
        if session not in projects:
            name = os.path.basename(session)
            try:
                with open(os.path.join(session, "command.json"), encoding="utf-8") as f:
                    cmd = json.load(f).get("cmd", [])
                if "--source_video" in cmd:
                    source = cmd[cmd.index("--source_video") + 1]
                    name = os.path.splitext(os.path.basename(source.replace("\\", "/")))[0] or name
            except (OSError, ValueError, TypeError, IndexError, AttributeError):
                pass
            projects[session] = name
    videos = [v for v in videos if v.get("project") in projects]
    choices = [(f"{name} · {sum(v['project'] == path for v in videos)} videos · {os.path.basename(path)}", path)
               for path, name in projects.items()]
    selected = project if project in projects else (choices[0][1] if choices else None)
    return videos, gr.update(choices=choices, value=selected)


def publisher_video_status(path):
    from shortsflow import settings, schedule
    done = settings.file_published_to(path)
    lines = ["**Published:** " + ", ".join(f"{platform} ({at})" for platform, at in done.items())] if done else ["**Not published yet**"]
    key = os.path.normcase(os.path.abspath(path))
    jobs = [job for job in schedule.jobs(ROOT) if os.path.normcase(os.path.abspath(job.get("path", ""))) == key]
    for job in jobs[-5:]:
        state = {"pending": "Waiting", "done": "Uploaded", "failed": "Failed", "cancelled": "Cancelled"}.get(job["status"], job["status"])
        lines.append(f"**{state}:** {job['at']} · `{job['id']}`" + (f" · {job.get('result', '')}" if job["status"] == "failed" else ""))
    return "\n\n".join(lines)


def publisher_card_publish(path, title, description, tags, platforms, privacy, account, again, preview=False):
    from shortsflow import schedule
    message = publisher_publish(path, None, title, description, tags, platforms, privacy, account, again, preview)
    return message, publisher_video_status(path), schedule.markdown(ROOT)


def publisher_card_schedule(path, title, description, tags, platforms, privacy, account, when):
    message, queue = publisher_schedule(path, None, title, description, tags, platforms, privacy, account, when)
    # The outcome belongs beside its button, including invalid/past time errors.
    return message, publisher_video_status(path), queue


def publisher_choices(shape_label="All formats"):
    """The video dropdown: every finished video of the chosen format, newest first."""
    from shortsflow import settings
    videos = settings.list_videos(ROOT, shape=SHAPE_LABELS.get(shape_label, "all"))
    return gr.update(choices=[(v["label"], v["path"]) for v in videos], value=(videos[0]["path"] if videos else None))


def publisher_pick(path):
    """What a chosen video fills in: the player, and a title, description and tags to start from."""
    from shortsflow import settings
    if not path or not os.path.isfile(path):
        return None, "", "", ""
    title, description, tags = settings.default_details(path)
    return path, title, description, ", ".join(tags)


def publisher_publish(path, upload, title, description, tags, platforms, privacy, account, again, preview):
    """Publish (or preview) one chosen video. A video from the library must lie in the sessions folder; an uploaded one is the person's own file."""
    from shortsflow import settings
    source = upload or path
    if not source:
        return "Pick a video from the list, or add one from this PC."
    if not upload:
        norm = lambda q: os.path.normcase(os.path.abspath(q))
        if not norm(source).startswith(norm(os.path.join(ROOT, "sessions")) + os.sep):
            return "That video is not in this app's sessions folder."
    ok, lines = settings.publish_file(source, title, description, tags, list(platforms or []), privacy=privacy, account=account, home=ROOT,
                                      dry_run=bool(preview), again=bool(again), env_path=ENV_PATH)
    head = "Preview (nothing was sent):" if preview else ("Published:" if ok else "Not published:")
    return head + "\n\n" + "\n\n".join(lines)


def publisher_schedule(path, upload, title, description, tags, platforms, privacy, account, when):
    """Queue the chosen video to be published at a later time. An uploaded file is copied into the sessions folder first so it is still there then."""
    from shortsflow import schedule
    source = upload or path
    if not source:
        return "Pick a video from the list, or add one from this PC.", schedule.markdown(ROOT)
    if upload:
        import shutil
        folder = os.path.join(ROOT, "sessions", "uploads")
        os.makedirs(folder, exist_ok=True)
        source = os.path.join(folder, os.path.basename(upload))
        if os.path.abspath(upload) != os.path.abspath(source):
            shutil.copy2(upload, source)
    else:
        norm = lambda q: os.path.normcase(os.path.abspath(q))
        if not norm(source).startswith(norm(os.path.join(ROOT, "sessions")) + os.sep):
            return "That video is not in this app's sessions folder.", schedule.markdown(ROOT)
    ok, message, _ = schedule.add(ROOT, source, when, title, description, tags, list(platforms or []), privacy=privacy, account=account)
    return message, schedule.markdown(ROOT)


def schedule_cancel(job_id):
    from shortsflow import schedule
    done = schedule.cancel(ROOT, (job_id or "").strip())
    return ("Cancelled." if done else "No waiting job has that id."), schedule.markdown(ROOT)


def with_auto_publish(stream):
    """Pass a run's (log, videos) stream through and, when auto-publish is on, publish the run that just finished and add the result to the log."""
    import time
    from shortsflow import settings
    since = time.time()
    log, last = "", None
    for log, videos in stream:
        last = (log, videos)
        yield log, videos
    try:
        lines = settings.auto_publish(ROOT, since)
    except Exception as e:                 # a publishing problem must never hide a finished video
        lines = [f"Auto-publish failed: {str(e)[:160]}"]
    if lines and last is not None:
        yield last[0] + "\n[Publish] " + "\n[Publish] ".join(lines) + "\n", last[1]


